            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "If, as I maintain and firmly believe, there is no objective definition of intelligence, and what we call intelligence is only a creation of cultural fashion and subjective prejudice, what the devil is it we test when we make use of an intelligence test?", Author = "Isaac Asimov" },
