            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "We can 'all' be members of the intellectual elite and then, and only then, will a phrase like \"America's right to know\" and, indeed, any true concept of democracy, have any meaning.", Author = "Isaac Asimov" },
