            new Quote { Id = "https://en.wikiquote.org/wiki/Isaac_Asimov", Text = "I get a certain pleasure in knowing that I live not merely in a city but in Manhattan, the center of New York City, a region so unique in many ways that I honestly believe that Earth is divided into halves: Manhattan and non-Manhattan.", Author = "Isaac Asimov" },
